mapper.select:
SELECT seq , title , link_url as linkUrl , target_type as targetType , file_name as fileName , original_file_name as originalFileName , display_order as displayOrder , is_active as isActive , reg_dt as regDt , mod_dt as modDt FROM TB_BANNER
ORDER BY display_order ASC, reg_dt DESC
LIMIT #{offset}, #{amount}

mapper.insert:
INSERT INTO TB_BANNER (
    title, link_url, target_type, file_name, original_file_name, display_order, is_active, reg_dt, mod_dt
) VALUES (
             #{title}, #{linkUrl}, #{targetType}, #{fileName}, #{originalFileName}, #{displayOrder}, #{isActive}, NOW(), NOW()
         )
